sys_script_include.script:
var autoTrackImportOnDemand = Class.create();
autoTrackImportOnDemand.prototype = {
    initialize: function () {
        // nothing needed here for now
    },

    /**
     * Load an attachment via a Data Source and run a Transform Map.
     *
     * @param {String} dataSourceSysId   sys_id of sys_data_source created for the uploaded Excel file
     * @param {String} transformMapSysId sys_id of the Transform Map (e.g. "Vehicle Inventory Additions")
     * @returns {Object}  { import_set_sys_id: "<sys_id>" } or null if something failed
     */
    importAndTransform: function (dataSourceSysId, transformMapSysId) {
        if (!dataSourceSysId || !transformMapSysId) {
            gs.error('autoTrackImportOnDemand.importAndTransform called without required parameters.');
            return null;
        }

        // 1. Get the Data Source record
        var grDataSource = new GlideRecord('sys_data_source');
        if (!grDataSource.get(dataSourceSysId)) {
            gs.error('autoTrackImportOnDemand: Data Source not found: ' + dataSourceSysId);
            return null;
        }

        // 2. Create an Import Set from the Data Source
        var importSetLoader = new GlideImportSetLoader();
        var grImportSet = importSetLoader.getImportSetGr(grDataSource);

        // Load the attachment into the import set table
        importSetLoader.loadImportSetTable(grImportSet, grDataSource);

        // Mark the import set as loaded
        grImportSet.setValue('state', 'loaded');
        grImportSet.update();

        // 3. Run the Transform Map against that Import Set
        var importSetTransformer = new GlideImportSetTransformer();
        importSetTransformer.setImportSetID(grImportSet.getUniqueValue());
        importSetTransformer.setMapID(transformMapSysId);
        importSetTransformer.setSyncImport(true); // run synchronously
        importSetTransformer.transformAllMaps(grImportSet);

        // 4. Return the import set sys_id so Flow / notifications can use it
        return {
            import_set_sys_id: grImportSet.getUniqueValue()
        };
    },

    type: 'autoTrackImportOnDemand'
};
